    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    if (todos.has(id)) {
      todos.delete(id);
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => {
    return Array.from(todos.values());
  };

  const listCompleted = (): Todo[] => {
    return Array.from(todos.values()).filter(todo => todo.completed);
  };

  const listPending = (): Todo[] => {
    return Array.from(todos.values()).filter(todo => !todo.completed);
  };

  const clearCompleted = (): void => {
    todos.forEach((value, key) => {
      if (value.completed) {
        todos.delete(key);
      }
    });
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
