let id = 0;
let todos: Todo[] = [];

export function createTodoApp(): TodoApp {
    const todoApp: TodoApp = {
        addTodo(text) {
            const newId = ++id;
            const todo = { id: newId, text, completed: false };
            todos.push(todo);
            return todo;
        },
        getTodo(id) {
            return todos.find(t => t.id === id);
        },
        toggleTodo(id) {
            const idx = todos.findIndex(t => t.id === id);
            if (idx !== -1) {
                todos[idx].completed = !todos[idx].completed;
            }
        },
        deleteTodo(id): boolean {
            let result = false;
            const index = todos.findIndex(todo => todo.id === id);
            if (index >= 0) {
                todos.splice(index, 1);
                result = true;
            }
            return result;
        },
        listTodos() {
            return todos.slice();
        },
        listCompleted() {
            return todos.filter(todo => todo.completed).slice();
        },
        listPending() {
            return todos.filter(todo => !todo.completed).slice();
        },
        clearCompleted() {
            const newTodos = todos.filter(todo => !todo.completed);
            todos = newTodos;
        }
    };
    return todoApp;
}

interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}
